/// <reference types="vite/client" />
// Lists that rust-core checks in under src-tauri/ (review 4, M-8 and N-14). They are generated by
// Rust tests, so the UI asserts against the real backend instead of its own copy of it. While a
// file is not checked in yet, the guard tests that need it are skipped and say why.

const FILES = import.meta.glob<unknown>("../../../../src-tauri/ipc-{passive,codes}.json", { eager: true, import: "default" });

/** Every string in the file: a flat array, objects with a `code`/`command`/`name`, or nested arrays/maps. */
function strings(raw: unknown): string[] {
  if (typeof raw === "string") return [raw];
  if (Array.isArray(raw)) return raw.flatMap(strings);
  if (raw !== null && typeof raw === "object") {
    const o = raw as Record<string, unknown>;
    for (const k of ["code", "command", "name"]) if (typeof o[k] === "string") return [o[k]];
    return Object.values(o).flatMap(strings);
  }
  return [];
}

function load(name: "ipc-passive.json" | "ipc-codes.json"): ReadonlySet<string> | null {
  const hit = Object.entries(FILES).find(([path]) => path.endsWith(`/src-tauri/${name}`));
  return hit ? new Set(strings(hit[1])) : null;
}

/** Commands that do not count as user activity for the idle lock (`PASSIVE_COMMANDS`). */
export const RUST_PASSIVE = load("ipc-passive.json");
/** Every `IpcError.code` the backend can return. */
export const RUST_CODES = load("ipc-codes.json");

export const missing = (name: string) => `skipped: src-tauri/${name} is not checked in yet (rust-core generates it)`;
